export function resourceColor(itemId, itemName = '') {
  if (Object.hasOwn(colors, itemId)) return colors[itemId];
  const key = String(itemId || itemName || 'material');
  let hash = 2166136261;
  for (const character of key) hash = Math.imul(hash ^ character.codePointAt(0), 16777619) >>> 0;
  const hue = hash % 360;
  const channel = (offset) => {
    const k = (offset + hue / 30) % 12;
    const value = 0.7 - 0.174 * Math.max(-1, Math.min(k - 3, 9 - k, 1));
    return Math.round(value * 255).toString(16).padStart(2, '0');
  };
  return `#${channel(0)}${channel(8)}${channel(4)}`;
}
